17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.ArrayList;
24	import java.util.Collection;
25	import java.util.List;
26	import java.util.Locale;
27	import java.util.regex.Pattern;
28	
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
40	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
41	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
42	import org.springframework.samples.petclinic.rest.api.OwnersApi;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
69	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
70	     * stored lower-cased.
71	     */
72	    private static final Pattern EMAIL_PATTERN =
73	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        validateRequiredOwnerFields(ownerFieldsDto);
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        owner.setAddress(normalizeAddress(owner.getAddress()));
125	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
126	        owner.setTelephone(normalizedTelephone);
127	        rejectDuplicateTelephone(normalizedTelephone);
128	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
129	        owner.setEmail(normalizeEmail(owner.getEmail()));
130	        if (owner.getRegistrationDate() == null) {
131	            owner.setRegistrationDate(LocalDate.now());
132	        }
133	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
134	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
135	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
136	        this.clinicService.saveOwner(owner);
137	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
138	        headers.setLocation(UriComponentsBuilder.newInstance()
139	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
140	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
146	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
147	        if (currentOwner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        currentOwner.setAddress(ownerFieldsDto.getAddress());
151	        currentOwner.setCity(ownerFieldsDto.getCity());
152	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
153	        currentOwner.setLastName(ownerFieldsDto.getLastName());
154	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
155	        this.clinicService.saveOwner(currentOwner);
156	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Transactional
161	    @Override
162	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
163	        Owner owner = this.clinicService.findOwnerById(ownerId);
164	        if (owner == null) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        this.clinicService.deleteOwner(owner);
168	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
174	        Owner owner = this.clinicService.findOwnerById(ownerId);
175	        if (owner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        HttpHeaders headers = new HttpHeaders();
179	        Pet pet = petMapper.toPet(petFieldsDto);
180	        owner.setId(ownerId);
181	        pet.setOwner(owner);
182	        pet.getType().setName(null);
183	        this.clinicService.savePet(pet);
184	        PetDto petDto = petMapper.toPetDto(pet);
185	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
186	            .buildAndExpand(pet.getId()).toUri());
187	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
193	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
194	        if (currentOwner != null) {
195	            Pet currentPet = this.clinicService.findPetById(petId);
196	            if (currentPet != null) {
197	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
198	                currentPet.setName(petFieldsDto.getName());
199	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
200	                this.clinicService.savePet(currentPet);
201	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
202	            }
203	        }
204	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
210	        HttpHeaders headers = new HttpHeaders();
211	        Visit visit = visitMapper.toVisit(visitFieldsDto);
212	        Pet pet = new Pet();
213	        pet.setId(petId);
214	        visit.setPet(pet);
215	        this.clinicService.saveVisit(visit);
216	        VisitDto visitDto = visitMapper.toVisitDto(visit);
217	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
218	            .buildAndExpand(visit.getId()).toUri());
219	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
220	    }
221	
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Override
225	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
226	        Owner owner = this.clinicService.findOwnerById(ownerId);
227	        if (owner != null) {
228	            Pet pet = owner.getPet(petId);
229	            if (pet != null) {
230	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
231	            }
232	        }
233	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
234	    }
235	
236	    /**
237	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
238	     * offending field is collected so the caller learns exactly which values must be supplied.
239	     *
240	     * @param ownerFieldsDto the submitted owner payload
241	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
242	     *         telephone is missing or blank
243	     */
244	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
245	        List<String> missingFields = new ArrayList<>();
246	        if (isBlank(ownerFieldsDto.getFirstName())) {
247	            missingFields.add("firstName");
248	        }
249	        if (isBlank(ownerFieldsDto.getLastName())) {
250	            missingFields.add("lastName");
251	        }
252	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
253	            missingFields.add("address");
254	        }
255	        if (isBlank(ownerFieldsDto.getCity())) {
256	            missingFields.add("city");
257	        }
258	        if (isBlank(ownerFieldsDto.getTelephone())) {
259	            missingFields.add("telephone");
260	        }
261	        if (!missingFields.isEmpty()) {
262	            throw new MissingOwnerFieldsException(missingFields);
263	        }
264	    }
265	
266	    private boolean isBlank(String value) {
267	        return value == null || value.isBlank();
268	    }
269	
270	    /**
271	     * Counts the existing owners who, before this create, already share the given first and last name.
272	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
273	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
274	     * case or spacing still count as the same name.
275	     *
276	     * @param firstName the first name of the owner being created
277	     * @param lastName the last name of the owner being created
278	     * @return the number of existing owners sharing both names (zero when none)
279	     */
280	    private int countNamesakes(String firstName, String lastName) {
281	        String first = normalizeHouseholdField(firstName);
282	        String last = normalizeHouseholdField(lastName);
283	        return (int) this.clinicService.findAllOwners().stream()
284	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
285	                && normalizeHouseholdField(existing.getLastName()).equals(last))
286	            .count();
287	    }
288	
289	    /**
290	     * Builds an owner's customer code, formatted '&lt;CITY3&gt;-&lt;LAST3&gt;-&lt;NNNN&gt;'. CITY3 is
291	     * the upper-cased first three letters of the city; LAST3 is the upper-cased first three letters of
292	     * the last name; NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
293	     * of owners already in that city (e.g. 'SYD-SMI-0007').
294	     *
295	     * @param city the owner's city
296	     * @param lastName the owner's last name
297	     * @return the formatted customer code
298	     */
299	    private String generateCustomerCode(String city, String lastName) {
300	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
301	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
302	        String normalizedCity = normalizeHouseholdField(city);
303	        int sequence = (int) this.clinicService.findAllOwners().stream()
304	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
305	            .count() + 1;
306	        return String.format("%s-%s-%04d", city3, last3, sequence);
307	    }
308	
309	    /**
310	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
311	     * customerCode is the owner's customer code and YY is the last two digits of the
312	     * registrationDate year (e.g. 'SMI-0007-M26').
313	     *
314	     * @param customerCode the owner's customer code
315	     * @param registrationDate the owner's registration date
316	     * @return the formatted membership number
317	     */
318	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
319	        String yy = String.format("%02d", registrationDate.getYear() % 100);
320	        return customerCode + "-M" + yy;
321	    }
322	
323	    /**
324	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
325	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
326	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
327	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
328	     * stored and returned.
329	     *
330	     * @param telephone the raw telephone value from the request
331	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
332	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
333	     */
334	    private String normalizeTelephone(String telephone) {
335	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
336	        String e164;
337	        if (cleaned.startsWith("+")) {
338	            e164 = cleaned;
339	        } else {
340	            String national = cleaned;
341	            if (national.startsWith("0")) {
342	                national = national.substring(1);
343	            }
344	            e164 = "+61" + national;
345	        }
346	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
347	            throw new InvalidOwnerFieldsException(List.of("telephone"));
348	        }
349	        return e164;
350	    }
351	
352	    /**
353	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
354	     * left unset. When a value is present it must be a syntactically valid address; the normalized
355	     * form stored and returned is the value lower-cased.
356	     *
357	     * @param email the raw email value from the request, or {@code null} when none was supplied
358	     * @return the lower-cased email, or {@code null} when no email was supplied
359	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
360	     */
361	    private String normalizeEmail(String email) {
362	        if (email == null || email.isBlank()) {
363	            return null;
364	        }
365	        if (!EMAIL_PATTERN.matcher(email).matches()) {
366	            throw new InvalidOwnerFieldsException(List.of("email"));
367	        }
368	        return email.toLowerCase(Locale.ROOT);
369	    }
370	
371	    /**
372	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
373	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
374	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
375	     * normalized form is what gets stored, returned and used for every address comparison (the
376	     * required-field check, household duplicate detection and the shared household id).
377	     *
378	     * @param address the raw address value from the request, or {@code null}
379	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
380	     */
381	    private String normalizeAddress(String address) {
382	        if (address == null) {
383	            return "";
384	        }
385	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
386	        if (collapsed.isEmpty()) {
387	            return "";
388	        }
389	        String[] tokens = collapsed.split(" ");
390	        for (int i = 0; i < tokens.length; i++) {
391	            switch (tokens[i]) {
392	                case "ST" -> tokens[i] = "STREET";
393	                case "RD" -> tokens[i] = "ROAD";
394	                case "AVE" -> tokens[i] = "AVENUE";
395	                default -> { }
396	            }
397	        }
398	        return String.join(" ", tokens);
399	    }
400	
401	    /**
402	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
403	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
404	     * directly and is therefore independent of the punctuation a caller supplied.
405	     *
406	     * @param e164Telephone the E.164 telephone of the owner being created
407	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
408	     */
409	    private void rejectDuplicateTelephone(String e164Telephone) {
410	        boolean inUse = this.clinicService.findAllOwners().stream()
411	            .map(Owner::getTelephone)
412	            .filter(existing -> existing != null)
413	            .anyMatch(e164Telephone::equals);
414	        if (inUse) {
415	            throw new DuplicateOwnerTelephoneException(e164Telephone);
416	        }
417	    }
418	
419	    /**
420	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
421	     * last name and a normalized address: last names are compared case-insensitively after whitespace
422	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
423	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
424	     * abbreviation still count as the same household.
425	     * <p>
426	     * When the owner's last name and address already belong to at least one other owner the behaviour
427	     * depends on {@code sharesHousehold}. If it is not true the create is rejected as a duplicate
428	     * household. If it is true the create is allowed and every member of the household - the existing
429	     * owners and this joiner - is assigned the same stable {@code householdId}, which is returned on
430	     * read. When no other owner shares the last name and address no identifier is assigned.
431	     *
432	     * @param owner the owner being created
433	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
434	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
435	     *         address and {@code sharesHousehold} is not true
436	     */
437	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
438	        String lastName = normalizeHouseholdField(owner.getLastName());
439	        String address = normalizeAddress(owner.getAddress());
440	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
441	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
442	                && normalizeAddress(existing.getAddress()).equals(address))
443	            .toList();
444	        if (housemates.isEmpty()) {
445	            return;
446	        }
447	        if (!Boolean.TRUE.equals(sharesHousehold)) {
448	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
449	        }
450	        String householdId = generateHouseholdId(lastName, address);
451	        owner.setHouseholdId(householdId);
452	        for (Owner housemate : housemates) {
453	            if (!householdId.equals(housemate.getHouseholdId())) {
454	                housemate.setHouseholdId(householdId);
455	                this.clinicService.saveOwner(housemate);
456	            }
457	        }
458	    }
459	
460	    /**
461	     * Builds the stable identifier shared by the members of one household. It is derived purely from
462	     * the normalized last name and address, so every owner of a given household deterministically
463	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
464	     * two normalized fields joined by a single space.
465	     *
466	     * @param normalizedLastName the household's last name, already normalized for comparison
467	     * @param normalizedAddress the household's address, already normalized for comparison
468	     * @return the shared household identifier
469	     */
470	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
471	        String key = normalizedLastName + '�' + normalizedAddress;
472	        try {
473	            byte[] digest = MessageDigest.getInstance("SHA-256")
474	                .digest(key.getBytes(StandardCharsets.UTF_8));
475	            StringBuilder hex = new StringBuilder();
476	            for (byte b : digest) {
477	                hex.append(String.format("%02X", b));
478	                if (hex.length() >= 12) {
479	                    break;
480	                }
481	            }
482	            return hex.substring(0, 12);
483	        } catch (NoSuchAlgorithmException e) {
484	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
485	        }
486	    }
487	
488	    /**
489	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
490	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
491	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
492	     * expands common abbreviations.
493	     *
494	     * @param value the raw last name, or {@code null}
495	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
496	     */
497	    private String normalizeHouseholdField(String value) {
498	        if (value == null) {
499	            return "";
500	        }
501	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
502	    }
503	}
